import React, { useState, useEffect } from "react";
import { FaSearch } from "react-icons/fa";
import jsPDF from "jspdf"; // Import jsPDF
import "jspdf-autotable"; // Import the jsPDF plugin for tables
import axios from "axios";
import { Link } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import "./SearchBar.css"; // Assuming you have custom CSS for the search bar

const AllOrders = () => {
  const [orders, setOrders] = useState([]);
  const [showAlert, setShowAlert] = useState(false);
  const [alertMessage, setAlertMessage] = useState("");
  const [showConfirmDialog, setShowConfirmDialog] = useState(false);
  const [confirmDialogData, setConfirmDialogData] = useState(null);
  const [searchQuery, setSearchQuery] = useState(""); // State for search query

  useEffect(() => {
    function getOrders() {
      axios
        .get("http://localhost:5555/orders/")
        .then((res) => {
          setOrders(Array.isArray(res.data.data) ? res.data.data : []);
        })
        .catch((err) => alert(err.message));
    }

    getEvents();
  }, []);

  const handleDeleteClick = (order) => {
    setConfirmDialogData(order);
    setShowConfirmDialog(true);
  };

  const handleDelete = () => {
    if (confirmDialogData) {
      axios
        .delete(`http://localhost:5555/orders/${confirmDialogData._id}`)
        .then(() => {
          setAlertMessage("Order deleted successfully!");
          setShowAlert(true);
          setTimeout(() => setShowAlert(false), 3000); // Hide after 3 seconds
          setOrders(orders.filter((order) => order._id !== confirmDialogData._id));
        })
        .catch((err) => {
          setAlertMessage("Error deleting order.");
          setShowAlert(true);
          setTimeout(() => setShowAlert(false), 3000);
        });
      setShowConfirmDialog(false);
    }
  };

  const handleCancel = () => {
    setShowConfirmDialog(false);
  };

  // Filter items based on search query
  const filterOrders = orders.filter(
    (order) =>
      order.orderId.toLowerCase().includes(searchQuery.toLowerCase()) 
     
  );

  // Function to download the report as a PDF
  const generateReport = () => {
    const doc = new jsPDF(); // Initialize jsPDF
    doc.text("Order Management Report", 14, 16); // Add a title

    const columns = ["firstName", "lastName", "email", "phoneNumber", "address", "city", "orderId", "specialInstructions", "pickupTime", "orderStatus"];
    const rows = filteredOrders.map((order) => [
      order.firstName,
      order.lastName,
      order.email,
      order.phoneNumber,
      order.address,
      order.city,
      order.orderId,
      order.specialInstructions,
      order.pickupTime,
      order.orderStatus,
    ]);

    doc.autoTable({
      head: [columns],
      body: rows,
      startY: 22,
    });

    doc.save("Orders_report.pdf");
  };

  return (
    <div style={containerStyle}>
      <h1 style={headerStyle}>All Orders</h1> {/* Title before the search bar */}

      {/* Centered Search Bar */}
      <div style={searchWrapperStyle}>
        <SearchBar onSearch={(query) => setSearchQuery(query)} />
      </div>

      <table style={tableStyle}>
        <thead>
          <tr>
            <th style={tableHeaderStyle}>First Name</th>
            <th style={tableHeaderStyle}>Last Name</th>
            <th style={tableHeaderStyle}>Email</th>
            <th style={tableHeaderStyle}>Phone Number</th>
            <th style={tableHeaderStyle}>Address</th>
            <th style={tableHeaderStyle}>City</th>
            <th style={tableHeaderStyle}>Order Id</th>
            <th style={tableHeaderStyle}>Speccial Instructions</th>
            <th style={tableHeaderStyle}>Pickup Time</th>
            <th style={tableHeaderStyle}>Order Status</th>
            <th style={tableHeaderStyle}></th>
            <th style={tableHeaderStyle}></th>
          </tr>
        </thead>
        <tbody>
          {filteredOrders.length > 0 ? (
            filteredOrders.map((order) => (
              <tr key={order._id} style={tableRowStyle}>
                <td style={tableCellStyle}>{order.firstName}</td>
                <td style={tableCellStyle}>{order.lastName}</td>
                <td style={tableCellStyle}>{order.email}</td>
                <td style={tableCellStyle}>{order.phoneNumber}</td>
                <td style={tableCellStyle}>{order.address}</td>
                <td style={tableCellStyle}>{order.city}</td>
                <td style={tableCellStyle}>{order.orderId}</td>
                <td style={tableCellStyle}>{order.specialInstructions}</td>
                <td style={tableCellStyle}>{order.pickupTime}</td>
                <td style={tableCellStyle}>{order.orderStatus}</td>

                <td style={tableCellStyle}>
                  <Link to={`/orders/${order._id}`} style={{ color: "#800000", textDecoration: "none" }}>
                    View Profile
                  </Link>
                </td>
                <td style={tableCellStyle}>
                  <button onClick={() => handleDeleteClick(order)} style={buttonStyle}>
                    Delete
                  </button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="10" style={tableCellStyle}>
                No orders available
              </td>
            </tr>
          )}
        </tbody>
      </table>

      <AnimatePresence>
        {showAlert && (
          <motion.div
            style={alertStyle}
            initial={{ opacity: 0, x: "100%" }}
            animate={{ opacity: 1, x: "0%" }}
            exit={{ opacity: 0, x: "100%" }}
          >
            {alertMessage}
          </motion.div>
        )}
      </AnimatePresence>

      {showConfirmDialog && (
        <div style={confirmDialogOverlayStyle}>
          <div style={confirmDialogStyle}>
            <h2 style={confirmDialogTitleStyle}>Confirm Deletion</h2>
            <p style={confirmDialogTextStyle}>Are you sure you want to delete this order?</p>
            <div style={confirmDialogButtonContainerStyle}>
              <button onClick={handleDelete} style={confirmDialogDeleteButtonStyle}>
                Yes, Delete
              </button>
              <button onClick={handleCancel} style={confirmDialogCancelButtonStyle}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Centered Generate Report Button */}
      <div style={generateReportButtonContainer}>
        <button onClick={generateReport} style={downloadButtonStyle}>
          Generate Report
        </button>
      </div>
    </div>
  );
};

// SearchBar Component for filtering events
const SearchBar = ({ onSearch }) => {
  const [searchQuery, setSearchQuery] = useState("");

  const handleSearch = (e) => {
    setSearchQuery(e.target.value);
    onSearch(e.target.value);
  };

  return (
    <div className="search-bar" style={searchBarStyle}>
      <input
        type="text"
        placeholder="Search orders..."
        value={searchQuery}
        onChange={handleSearch}
        style={searchInputStyle}
      />
      <button type="submit" style={searchButtonStyle}>
        <FaSearch />
      </button>
    </div>
  );
};

